contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address nonOwner) public {
        vm.assume(sender != address(0) && sender != address(this));
        vm.assume(nonOwner != address(0) && nonOwner != sender && nonOwner != address(this));

        // Initialize and set up
        c.initialize();

        // Set sender as program operator
        vm.prank(sender);
        c.initialize();

        // Deploy a dummy implementation and alloSettings
        address impl = address(new DummyImplementation());
        address allo = address(new DummyAlloSettings());

        vm.prank(sender);
        c.updateRoundImplementation(payable(impl));
        vm.prank(sender);
        c.updateAlloSettings(allo);

        // Try to create as non-owner (should revert in reference, pass in mutant)
        vm.prank(nonOwner);
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.create.selector, "", address(0))
        );

        // In reference: onlyOwner check on transferOwnership would fail because nonOwner is not owner
        // In mutant: onlyOwner is bypassed, so the call might succeed but ownership remains with sender
        assertTrue(success == false || c.owner() == sender);
    }
}

contract DummyImplementation {
    function initialize(bytes calldata, address) external {}
}

contract DummyAlloSettings {}

