pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes calldata encodedParameters, address ownedBy) public {
        // Bound/assume to avoid unrealistic cases
        vm.assume(caller != address(0) && ownedBy != address(0));

        // Ensure the contract is initialized
        c.initialize();

        // Setup: make caller a program operator, and ensure enough ETH for the call
        // (the create function doesn't need ETH, but just in case)
        uint256 balanceBefore = address(c).balance;
        vm.deal(caller, 1 ether);
        vm.prank(caller);

        // Try to call create
        bool success;
        bytes memory errorData;
        bool isOperator = c.programOperators(caller);
        if (!isOperator) {
            // First make them an operator so we can test the non-operator case separately
            // We'll test the non-operator case directly
            (success, errorData) = address(c).call(abi.encodeWithSignature("create(bytes,address)", encodedParameters, ownedBy));
            // For non-operator, should revert
            vm.assume(!success); // If it succeeded despite not being operator, skip
        } else {
            // Call create as operator
            (success, errorData) = address(c).call(abi.encodeWithSignature("create(bytes,address)", encodedParameters, ownedBy));

            if (success) {
                // After successful create, initialize should revert
                bool initReverted;
                try c.initialize() {
                    initReverted = false;
                } catch {
                    initReverted = true;
                }
                assertTrue(initReverted, "initialize should revert after successful create");
            } else {
                // If create reverted, initialize should still work
                bool initReverted;
                try c.initialize() {
                    initReverted = false;
                } catch {
                    initReverted = true;
                }
                assertTrue(!initReverted, "initialize should not revert after failed create");
            }
        }
    }
}

